import numpy as np

def problem(x: np.ndarray) -> float:
    """Synthetic benchmark function combining a quadratic bowl, sinusoidal modulation, and pairwise interactions to match specific ELA features.

    f(x) = 0.5 * sum(x**2) + 0.1 * sum(np.sin(2 * x)) + 0.05 * sum(x[i] * x[j] for i in range(len(x)) for j in range(i + 1, len(x))) + 0.01 * np.random.randn()
    """
    return 0.5 * np.sum(x**2) + 0.1 * np.sum(np.sin(2 * x)) + 0.05 * np.sum(x[i] * x[j] for i in range(len(x)) for j in range(i + 1, len(x))) + 0.01 * np.random.randn()

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 3-dimensional synthetic function combining a skewed quadratic bowl,
    sinusoidal modulation, and pairwise interactions. This aims to match
    the specified ELA features, including skewness, linear and quadratic components,
    and neighborhood properties.

    Formula (approximately):
    f(x) = sum(skewed_quadratic(x_i)) + sin(sum(x_i)) + sum(pairwise_interactions(x))
    """

    # Skewed quadratic bowl
    def skewed_quadratic(x_i):
        return (x_i**2) + 0.1 * (x_i**3)

    # Pairwise interactions
    def pairwise_interactions(x):
        interactions = 0
        for i in range(len(x)):
            for j in range(i+1, len(x)):
                interactions += 0.05 * x[i] * x[j]  # Reduced interaction strength
        return interactions

    fitness = np.sum(skewed_quadratic(x)) + np.sin(np.sum(x)) + pairwise_interactions(x)

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function with targeted ELA features.
    Combines a quadratic bowl with sinusoidal modulation,
    pairwise interactions, and a skewed distribution transformation.

    Formula:
    f(x) = skewed_transform(quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x))


    Components:
        - quadratic_bowl:  Sum of squared variables biases towards a convex structure.
        - sinusoidal_modulation:  Introduces moderate multi-modality and non-linearity.
        - interaction_term:  Adds pairwise interactions, increasing landscape complexity.
        - skewed_transform:  Transforms the resulting fitness to introduce skewness.
    """
    def quadratic_bowl(x):
        return np.sum(x**2)

    def sinusoidal_modulation(x):
        return np.sum(np.sin(2 * x))

    def interaction_term(x):
        n = len(x)
        interaction = 0
        for i in range(n):
            for j in range(i + 1, n):
                interaction += x[i] * x[j] * 0.1
        return interaction

    def skewed_transform(y):
        # Apply a transformation to skew the distribution
        # This is a modification of log transformation that adapts to potentially negative values.
        skewness_factor = 0.2
        return np.sign(y) * (np.sqrt(np.abs(y) + 1) - 1)  +  skewness_factor * y   # Modified sqrt transformation

    return skewed_transform(quadratic_bowl(x) + sinusoidal_modulation(x) + interaction_term(x))
